import{_ as e,o as a,c as d,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const x=JSON.parse('{"title":"信号质量要求","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《DDR SIPI训练营》学习笔记/02-信号质量要求.md","filePath":"notes/《DDR SIPI训练营》学习笔记/02-信号质量要求.md","lastUpdated":1795350812000}'),n={name:"notes/《DDR SIPI训练营》学习笔记/02-信号质量要求.md"};function r(s,t,i,o,D,p){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="信号质量要求" tabindex="-1">信号质量要求 <a class="header-anchor" href="#信号质量要求" aria-label="Permalink to &quot;信号质量要求&quot;">​</a></h1><h2 id="一判断信号质量的三个方面" tabindex="-1">一、判断信号质量的三个方面 <a class="header-anchor" href="#一判断信号质量的三个方面" aria-label="Permalink to &quot;一、判断信号质量的三个方面&quot;">​</a></h2><p>了解了 SSTL（Stub Series Terminated Logic，短截线串联端接逻辑）这种逻辑，知道了参数调整之后信号变化的大体趋势。</p><p>调整参数之后信号有变化、眼图有变化，到底哪一种质量更好，该选哪种配置，需要有标准来判断信号质量。</p><p>DDR 接口里的信号质量比较复杂，要求的东西比较多，大体是三个方面：波形、时序、眼图。</p><h2 id="二波形质量过冲下冲与面积限制" tabindex="-1">二、波形质量：过冲、下冲与面积限制 <a class="header-anchor" href="#二波形质量过冲下冲与面积限制" aria-label="Permalink to &quot;二、波形质量：过冲、下冲与面积限制&quot;">​</a></h2><p>波形的要求比较简单，就是普通的过冲、下冲，这是一种电气安全上的要求。</p><p>以 DDR3L 为例，过冲峰值不能超过 0.4 V，下冲峰值也不能超过 0.4 V。</p><p>还有一个面积限制：信号可以超过 1.35 V，就算没有达到最大峰值，超过 1.35 V 这个高电平的时间太长也不行。限制的是面积，也就是积累电荷的总量，不至于导致输入缓冲击穿。</p><p>这个面积手工算不出来。实际仿真里信号确实超过逻辑高电平 1.35 V，软件会自动计算超过那一部分的积分，再拿去对比。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1795338755797-dfcc0536-5632-4682-809c-2613a4ca51ce.svg" alt="过冲与下冲的面积限制示意"></p><table tabindex="0"><thead><tr><th style="text-align:left;">英文标注</th><th style="text-align:left;">中文对照</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">Volts (V)</td><td style="text-align:left;">伏特（电压）</td><td style="text-align:left;">纵轴的电压单位。</td></tr><tr><td style="text-align:left;">VDDQ</td><td style="text-align:left;">DDR 电源高电平（Voltage Drain Drain for Data Queue，DQ 供电电压）</td><td style="text-align:left;">图里两条水平线的上边一条；DDR3L 的逻辑高电平是 1.35 V。</td></tr><tr><td style="text-align:left;">VSSQ</td><td style="text-align:left;">DDR 电源低电平（DQ 地）</td><td style="text-align:left;">两条水平线的下边一条；对应低电平 0 V。</td></tr><tr><td style="text-align:left;">Maximum Amplitude</td><td style="text-align:left;">最大幅度</td><td style="text-align:left;">过冲、下冲允许的最大峰值，DDR3L 都不能超过 0.4 V。</td></tr><tr><td style="text-align:left;">Overshoot Area</td><td style="text-align:left;">过冲面积</td><td style="text-align:left;">信号超过 VDDQ 那一部分的面积；面积不能超过限定值。</td></tr><tr><td style="text-align:left;">Undershoot Area</td><td style="text-align:left;">下冲面积</td><td style="text-align:left;">信号低于 VSSQ 那一部分的面积；面积不能超过限定值。</td></tr><tr><td style="text-align:left;">Time (ns)</td><td style="text-align:left;">时间（纳秒）</td><td style="text-align:left;">横轴的时间单位。</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:center;">DDR3L-800</th><th style="text-align:center;">DDR3L-1066</th><th style="text-align:center;">DDR3L-1333</th><th style="text-align:center;">DDR3L-1600</th><th style="text-align:center;">DDR3L-1866</th><th style="text-align:center;">DDR3L-2133</th></tr></thead><tbody><tr><td style="text-align:left;">Maximum peak amplitude allowed for overshoot area</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td></tr><tr><td style="text-align:left;">Maximum peak amplitude allowed for undershoot area</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td><td style="text-align:center;">0.4 V</td></tr><tr><td style="text-align:left;">Maximum overshoot area above VDDQ/VDDQ</td><td style="text-align:center;">0.25 V/ns</td><td style="text-align:center;">0.19 V/ns</td><td style="text-align:center;">0.15 V/ns</td><td style="text-align:center;">0.13 V/ns</td><td style="text-align:center;">0.11 V/ns</td><td style="text-align:center;">0.10 V/ns</td></tr><tr><td style="text-align:left;">Maximum undershoot area below VSSQ/VSSQ</td><td style="text-align:center;">0.25 V/ns</td><td style="text-align:center;">0.19 V/ns</td><td style="text-align:center;">0.15 V/ns</td><td style="text-align:center;">0.13 V/ns</td><td style="text-align:center;">0.11 V/ns</td><td style="text-align:center;">0.10 V/ns</td></tr></tbody></table><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1795334644896-c7b8d48c-1994-4345-adaf-ea0ace1f5f4e.svg" alt="没有触发过冲、下冲的波形"></p><p>这个波形虽然有上冲毛刺，但没有过冲、没有下冲：DDR3L 的逻辑高电平是 1.35 V，信号没有超过它，低电平也没有跑到 0 V 以下。</p><h2 id="三时序建立时间保持时间与转换速率" tabindex="-1">三、时序：建立时间、保持时间与转换速率 <a class="header-anchor" href="#三时序建立时间保持时间与转换速率" aria-label="Permalink to &quot;三、时序：建立时间、保持时间与转换速率&quot;">​</a></h2><p>DDR3 接口最典型的特点是，绝大多数定义都是基于时序的，出发点是<strong>建立时间</strong>和<strong>保持时间</strong>。</p><p>DDR2 和 DDR3 都是这种定义方法，到了 DDR4 这种定义就变了，但 DDR3 没变，还得按这种定义来做。</p><p>以 DDR3L-1066 为例，在 AC160 这个判断电平上，建立时间必须大于 40 ps，保持时间必须大于 110 ps。</p><p>计算这个建立时间和保持时间是以参考时钟，也就是 DQS 差分波形的交叉点为基准：</p><p>建立时间用 AC 门线和眼图的交叉点为起始点来算的；</p><p>保持时间是 DQS 交叉点所在的时间，眼图与 DC 门线的交叉点所在的时间，这两个位置的时间差，要满足规范定义的最小时间。</p><p>这样眼图张开的程度就要有一定的宽度，建立时间、保持时间的定义决定了眼图最小宽度不能小于多少。</p><p>建立时间和保持时间还和信号的斜率有关。</p><p>SPEC里的定义是以 1 V/ns 的斜率做的；</p><p>如果斜率达不到 1 V/ns，就要对建立时间、保持时间做校正。</p><table tabindex="0"><thead><tr><th>Parameter</th><th>条件</th><th>Symbol</th><th>DDR3L-800 Min</th><th>DDR3L-1066 Min</th></tr></thead><tbody><tr><td>Data setup time to DQS, DQS#</td><td>Base (specification)</td><td>tDS (AC160)</td><td>90</td><td><strong>40</strong></td></tr><tr><td>Data setup time to DQS, DQS#</td><td>VREF @ 1 V/ns</td><td>tDS (AC160)</td><td>250</td><td>200</td></tr><tr><td>Data setup time to DQS, DQS#</td><td>Base (specification)</td><td>tDS (AC135)</td><td>140</td><td>90</td></tr><tr><td>Data setup time to DQS, DQS#</td><td>VREF @ 1 V/ns</td><td>tDS (AC135)</td><td>275</td><td>250</td></tr><tr><td>Data hold time from DQS, DQS#</td><td>Base (specification)</td><td>tDH (DC90)</td><td>160</td><td><strong>110</strong></td></tr><tr><td>Data hold time from DQS, DQS#</td><td>VREF @ 1 V/ns</td><td>tDH (DC90)</td><td>250</td><td>200</td></tr></tbody></table><p>DDR3 接口的时序要求是其他参数定义的出发点，也是评估信号质量的出发点。</p><p>因为有了时序的需求，才对眼图提出了一定的要求。</p><h2 id="四眼图孔径宽度电压余量与-tvac" tabindex="-1">四、眼图：孔径宽度、电压余量与 tVAC <a class="header-anchor" href="#四眼图孔径宽度电压余量与-tvac" aria-label="Permalink to &quot;四、眼图：孔径宽度、电压余量与 tVAC&quot;">​</a></h2><p>评估 DDR 接口通常用眼图。因为有时序需求，眼图需要有一定的宽度。建立时间和保持时间与 AC 门线、DC 门线有关，在眼图里用AC 门线和DC 门线这两个值画出图形，时间轴上的宽度叫<strong>孔径时间</strong>。如果这个宽度足够宽，就能满足建立时间和保持时间的要求。</p><p>评估信号质量一个非常重要的指标就是孔径时间的宽度，也就是 <strong>ApertureWidth</strong>。</p><p>这个宽度如果比较大的话，就决定了抖动不能太大，抖动和孔径时间有一定关联。</p><p>除了时间轴上的要求之外，还有<strong>电压余量</strong>（Voltage margin）。</p><p><strong>电压余量</strong>指的是信号在高电平或低电平可能会有波动，最低的那个值和 DC 门线之间的电压差就是<strong>余量</strong>。</p><p>真正计算时，应该从 DQS 交叉点对应的时间点去算；按眼图最低点算比较严格。</p><p>电压余量大，设计时比较保险。孔径宽度和电压余量这两个值都要尽量大，也就是眼图要睁得足够大。</p><p>还有 tVAC：</p><p>信号必须超过 AC 门线，超过之后必须保持的最小时间，这种定义通常只在负载极重时才会遇到。</p><p>一般情况下，如果是属于Memory Down 的设计，也就是说，所有的DDR颗粒都是焊在板子上的这种情况，比如说四片的、五片的、八片的，这种负载都不是很重，大多数场景下不是问题；只有极重负载才需要考虑。</p><h2 id="五差分信号的交叉点偏移-vix" tabindex="-1">五、差分信号的交叉点偏移 Vix <a class="header-anchor" href="#五差分信号的交叉点偏移-vix" aria-label="Permalink to &quot;五、差分信号的交叉点偏移 Vix&quot;">​</a></h2><p>差分信号的输入有一个 Vix 的要求，比如 DQS 信号，交叉点偏离 VREF 电压不能太大，向上、向下都不能超过 150 mV。</p><p>这个规定的原因还是在于建立时间、保持时间的要求。</p><p>假如差分对 P 端和 N 端有一定的偏斜，交叉点就偏离 VREF二分之一接口电压（VDD/2）。</p><p>计算建立时间和保持时间时，是以这个交叉点为基准的。</p><p>交叉点偏移之后，建立时间延长，保持时间变小；偏斜太多，保持时间有可能达不到SPEC。</p><p>差分信号本身是时间基准，它的交叉点是测量建立时间、保持时间的基准，不能偏得太多，所以有 Vix 要求。</p>',47)])])}const h=e(n,[["render",r]]);export{x as __pageData,h as default};
